//! Fixed finance fixture arithmetic and three-run evidence grading.
use crate::{Result,cli::Args,canonical::sha256};
use serde_json::{Value,json};
use std::{collections::{BTreeMap,BTreeSet},path::Path};
const DIR:&str="src/services/eval/fixtures/real_finance_salesforce_fy26_q1";
fn load(path:impl AsRef<Path>)->Result<Value>{let v=crate::strict_json::parse(&std::fs::read(path)?)?;if !v.is_object(){return Err("fixture must contain one JSON object".into())}Ok(v)}
fn list(v:&Value)->&[Value]{v.as_array().map(Vec::as_slice).unwrap_or(&[])}
fn set(v:&Value)->BTreeSet<&str>{list(v).iter().filter_map(Value::as_str).collect()}
fn num(v:&Value)->Result<f64>{v.as_f64().filter(|n|n.is_finite()).ok_or_else(||"expected finite numeric fixture value".into())}
fn hash_valid(v:&Value)->bool{v.as_str().is_some_and(|s|s.len()==64&&s.bytes().all(|b|b.is_ascii_digit()||(b'a'..=b'f').contains(&b)))}
pub fn calculations(inputs:&Value)->Result<BTreeMap<String,f64>>{let q=&inputs["q1"];let fy=&inputs["fy25"];let qv=|k:&str|num(&q[k]);let fv=|k:&str|num(&fy[k]);let qfcf=qv("cfo_2025")?-qv("capex_2025")?;let pfcf=qv("cfo_2024")?-qv("capex_2024")?;let gaap=qv("gaap_operating_income_2025")?/qv("revenue_2025")?;let prior_gaap=qv("gaap_operating_income_2024")?/qv("revenue_2024")?;let non_gaap=qv("non_gaap_operating_income_2025")?/qv("revenue_2025")?;let prior_non_gaap=qv("non_gaap_operating_income_2024")?/qv("revenue_2024")?;let wc=list(&q["working_capital_changes_2025"]).iter().map(num).collect::<Result<Vec<_>>>()?.iter().sum::<f64>();let addbacks=list(&q["non_gaap_addbacks_2025"]).iter().map(num).collect::<Result<Vec<_>>>()?.iter().sum::<f64>();let fcf25=fv("cfo_2025")?-fv("capex_2025")?;let fcf24=fv("cfo_2024")?-fv("capex_2024")?;let quick=(qv("cash_2025")?+qv("marketable_securities_2025")?+qv("accounts_receivable_2025")?)/qv("current_liabilities_2025")?;let fyquick=(fv("cash_2025")?+fv("marketable_securities_2025")?+fv("accounts_receivable_2025")?)/fv("current_liabilities_2025")?;let cash=qv("cash_2025")?+qv("marketable_securities_2025")?-qv("debt_2025")?;let fycash=fv("cash_2025")?+fv("marketable_securities_2025")?-fv("debt_2025")?;
 Ok([("q1_revenue_growth_pct",(qv("revenue_2025")?/qv("revenue_2024")?-1.)*100.),("q1_gaap_operating_margin_pct",gaap*100.),("q1_prior_gaap_operating_margin_pct",prior_gaap*100.),("q1_gaap_margin_expansion_bps",(gaap-prior_gaap)*10000.),("q1_non_gaap_operating_margin_pct",non_gaap*100.),("q1_non_gaap_margin_expansion_bps",(non_gaap-prior_non_gaap)*10000.),("q1_non_gaap_addbacks_usd_m",addbacks),("q1_addbacks_pct_gaap_operating_income",addbacks/qv("gaap_operating_income_2025")?*100.),("q1_fcf_usd_m",qfcf),("q1_fcf_growth_pct",(qfcf/pfcf-1.)*100.),("q1_cfo_to_net_income_x",qv("cfo_2025")?/qv("net_income_2025")?),("q1_disclosed_working_capital_cash_benefit_usd_m",wc),("q1_working_capital_share_of_cfo_net_income_gap_pct",wc/(qv("cfo_2025")?-qv("net_income_2025")?)*100.),("q1_current_ratio_x",qv("current_assets_2025")?/qv("current_liabilities_2025")?),("q1_quick_ratio_x",quick),("q1_net_cash_including_marketable_usd_m",cash),("q1_cash_only_minus_debt_usd_m",qv("cash_2025")?-qv("debt_2025")?),("q1_interest_coverage_x",qv("gaap_operating_income_2025")?/qv("interest_expense_2025")?),("fy25_fcf_usd_m",fcf25),("fy25_fcf_growth_pct",(fcf25/fcf24-1.)*100.),("fy25_cfo_to_net_income_x",fv("cfo_2025")?/fv("net_income_2025")?),("fy24_cfo_to_net_income_x",fv("cfo_2024")?/fv("net_income_2024")?),("mechanical_q1_annualized_fcf_usd_m",qfcf*4.),("q1_net_cash_increase_from_fy25_usd_m",cash-fycash),("q1_quick_ratio_change_from_fy25_x",quick-fyquick)].into_iter().map(|(k,v)|(k.into(),v)).collect())}
pub async fn validate_fixture(dir:&Path,verify_source_bytes:bool)->Result<Value>{let golden=load(dir.join("golden.v1.json"))?;let sources=load(dir.join("sources.v1.json"))?;let packet=std::fs::read(dir.join(sources["source_packet"]["path"].as_str().ok_or("packet path required")?))?;let hash=sha256(&packet);if sources["source_packet"]["sha256"]!=hash{return Err("source packet SHA-256 mismatch".into())}let calculated=calculations(&golden["inputs"])?;let metrics=golden["metrics"].as_array().filter(|a|!a.is_empty()).ok_or("golden metrics must be a non-empty array")?;let points=metrics.iter().map(|m|num(&m["points"]).map(|n|n as i64)).collect::<Result<Vec<_>>>()?.iter().sum::<i64>();if points!=50{return Err("golden metric points must sum to 50".into())}let points=list(&golden["required_conclusions"]).iter().map(|m|num(&m["points"]).map(|n|n as i64)).collect::<Result<Vec<_>>>()?.iter().sum::<i64>();if points!=25{return Err("golden conclusion points must sum to 25".into())}for m in metrics{let id=m["id"].as_str().ok_or("metric id required")?;let actual=calculated.get(id).ok_or_else(||format!("no independent formula for {id}"))?;let expected=num(&m["expected"])?;let tolerance=(num(&m["tolerance_abs"])?/10.).max(1e-9);if !actual.is_finite()||(expected-actual).abs()>tolerance{return Err(format!("golden value does not match formula: {id}").into())}}
 let mut source_results=vec![];if verify_source_bytes{let client=reqwest::Client::builder().timeout(std::time::Duration::from_secs(30)).build()?;for source in list(&sources["documents"]){let data=client.get(source["url"].as_str().ok_or("source URL required")?).header("User-Agent","AI-Platform finance eval research eval@example.invalid").send().await?.error_for_status()?.bytes().await?;if source["sha256"]!=sha256(&data)||source["bytes"].as_u64()!=Some(data.len()as u64){return Err(format!("pinned source bytes changed: {}",source["source_id"]).into())}source_results.push(json!({"source_id":source["source_id"],"verified":true}));}}Ok(json!({"fixture_valid":true,"task_id":golden["task_id"],"metric_count":metrics.len(),"source_packet_sha256":hash,"source_bytes":source_results}))}
pub fn delegation(subagents:&Value,allowed:&BTreeSet<&str>,packet:&str)->(f64,Vec<String>){let Some(children)=subagents.as_array().filter(|a|a.len()==3)else{return(0.,vec!["delegation must contain exactly three child receipts".into()])};let mut f=vec![];let roles=children.iter().filter(|c|c.is_object()).filter_map(|c|c["role"].as_str()).collect::<BTreeSet<_>>();if roles!=["gaap_filing_analyst","non_gaap_reconciliation_analyst","skeptical_credit_reviewer"].into_iter().collect(){f.push("delegation roles do not match the required independent specialists".into());}let batches=children.iter().filter(|c|c.is_object()).map(|c|c["batch_call_id"].as_str()).collect::<BTreeSet<_>>();if batches.len()!=1||batches.contains(&None)||batches.contains(&Some("")){f.push("children must share one non-empty batch_call_id".into());}let indexes=children.iter().filter(|c|c.is_object()).filter_map(|c|c["dispatch_index"].as_i64()).collect::<BTreeSet<_>>();if indexes!=[0,1,2].into_iter().collect(){f.push("dispatch indexes must be exactly 0, 1, and 2".into());}let ids=children.iter().filter(|c|c.is_object()).map(|c|c["terminal_receipt_id"].as_str()).collect::<BTreeSet<_>>();if ids.len()!=3||ids.contains(&None)||ids.contains(&Some("")){f.push("children must have three unique terminal receipt IDs".into());}let mut intervals=vec![];for child in children{if !child.is_object()||child["status"]!="completed"{f.push("every delegated child must have one completed terminal receipt".into());continue}let role=child["role"].as_str().unwrap_or("None");let timing=child["started_monotonic_ms"].as_f64().zip(child["finished_monotonic_ms"].as_f64());let Some((start,end))=timing.filter(|(s,e)|e>s)else{f.push(format!("invalid child timing receipt for role {role}"));continue};intervals.push((start,end));if !child["evidence_ids"].as_array().is_some_and(|a|!a.is_empty()){f.push(format!("child {role} has no evidence receipt"));}else if list(&child["evidence_ids"]).iter().any(|v|!v.as_str().is_some_and(|s|allowed.contains(s))){f.push(format!("child {role} used unapproved evidence"));}if child["input_artifact_sha256"]!=packet{f.push(format!("child {role} is not bound to the fixed packet"));}if child["side_effects"]!=json!([]){f.push(format!("child {role} did not remain read-only"));}}if intervals.len()==3&&intervals.iter().map(|(s,_)|*s).fold(f64::NEG_INFINITY,f64::max)>=intervals.iter().map(|(_,e)|*e).fold(f64::INFINITY,f64::min){f.push("three specialist intervals did not overlap concurrently".into());}(if f.is_empty(){10.}else{0.},f)}
pub fn evaluate_run(run:&Value,golden:&Value,packet:&str)->Result<Value>{if !run.is_object(){return Ok(json!({"score":0.0,"passed":false,"failures":["run is not an object"]}))}let(mut cap,mut metric_score,mut citation_score)=(100f64,0f64,10f64);let mut failures=vec![];let allowed=set(&golden["allowed_evidence_ids"]);let metrics=&run["metrics"];if !metrics.is_object(){failures.push("metrics must be an object".into());}for metric in list(&golden["metrics"]){let id=metric["id"].as_str().ok_or("metric id required")?;let entry=&metrics[id];let value=entry["value"].as_f64().filter(|n|n.is_finite());let evidence=if value.is_some()&&list(&entry["evidence_ids"]).iter().all(Value::is_string){set(&entry["evidence_ids"])}else{BTreeSet::new()};let correct=value.is_some_and(|v|(v-num(&metric["expected"]).unwrap_or(f64::NAN)).abs()<=num(&metric["tolerance_abs"]).unwrap_or(-1.));let grounded=!evidence.is_empty()&&!evidence.is_disjoint(&set(&metric["evidence_ids"]));if correct{metric_score+=num(&metric["points"])?;}else{failures.push(format!("metric incorrect or missing: {id}"));if metric["critical"]==true{cap=cap.min(75.);}}if !grounded{citation_score-=10./list(&golden["metrics"]).len()as f64;failures.push(format!("metric lacks required evidence: {id}"));}if !evidence.is_subset(&allowed){cap=cap.min(70.);failures.push(format!("metric uses unapproved evidence: {id}"));}}
 let mut conclusion_score=0.;for r in list(&golden["required_conclusions"]){let id=r["id"].as_str().ok_or("conclusion id required")?;if run["conclusions"][id]==r["expected"]{conclusion_score+=num(&r["points"])?;}else{cap=cap.min(num(&r["hard_cap_on_failure"])?);failures.push(format!("required conclusion failed: {id}"));}}let(delegation_score,delegation_failures)=delegation(&run["subagents"],&allowed,packet);if !delegation_failures.is_empty(){cap=cap.min(85.);}failures.extend(delegation_failures);let mut trace_score=5.;if run["status"]!="completed"{trace_score=0.;cap=0.;failures.push("run status is not completed".into());}if !hash_valid(&run["final_answer_sha256"]){trace_score=0.;cap=cap.min(90.);failures.push("missing valid final-answer SHA-256 receipt".into());}let raw=metric_score+conclusion_score+citation_score.max(0.)+delegation_score+trace_score;let score=raw.min(cap);Ok(json!({"run_id":run["run_id"],"raw_score":raw,"hard_cap":cap,"score":score,"passed":score>=num(&golden["minimum_score"])?,"component_scores":{"metrics":metric_score,"conclusions":conclusion_score,"citations":citation_score.max(0.),"parallel_delegation":delegation_score,"trace_integrity":trace_score},"failures":failures}))}
pub async fn run(args:Args)->Result<(Value,i32)>{args.reject_unknown(&["output","fixture-only","verify-source-bytes"])?;if args.positional.len()>1{return Err("unexpected positional argument".into())}let fixture=validate_fixture(Path::new(DIR),args.options.contains_key("fixture-only")&&args.options.contains_key("verify-source-bytes")).await?;let report=if args.options.contains_key("fixture-only"){fixture}else{let path=args.positional.first().ok_or("receipt is required unless --fixture-only is used")?;let golden=load(Path::new(DIR).join("golden.v1.json"))?;let receipt=load(path)?;if receipt["schema_version"]!="real-finance-eval-receipt/v1"{return Err("unsupported receipt schema_version".into())}if receipt["task_id"]!=golden["task_id"]{return Err("receipt task_id mismatch".into())}let runs=receipt["runs"].as_array().filter(|a|Some(a.len()as u64)==golden["repetitions"].as_u64()).ok_or("critical finance case requires exactly three real runs")?;let ids=runs.iter().filter(|r|r.is_object()).map(|r|r["run_id"].as_str()).collect::<Vec<_>>();if ids.iter().collect::<BTreeSet<_>>().len()!=3||ids.iter().any(|id|id.is_none_or(str::is_empty)){return Err("run_id values must be three unique non-empty strings".into())}let packet=fixture["source_packet_sha256"].as_str().unwrap();let reports=runs.iter().map(|run|evaluate_run(run,&golden,packet)).collect::<Result<Vec<_>>>()?;let score=reports.iter().map(|r|r["score"].as_f64().unwrap()).fold(f64::INFINITY,f64::min);json!({"schema_version":"real-finance-evaluation-report/v1","task_id":golden["task_id"],"aggregation":"minimum_run_score","score":score,"passed":reports.iter().all(|r|r["passed"]==true)&&score>=num(&golden["minimum_score"])?,"minimum_score":golden["minimum_score"],"runs":reports,"note":"External LLM judge score must be combined as min(deterministic, judge) per run."})};if let Some(output)=args.options.get("output"){std::fs::write(output,format!("{}\n",serde_json::to_string_pretty(&report)?))?;}let code=if report.get("passed").unwrap_or(&report["fixture_valid"])==true{0}else{1};Ok((report,code))}
#[cfg(test)]mod tests{use super::*;#[test]fn delegation_requires_three_independent_receipts(){assert_eq!(delegation(&json!([]),&BTreeSet::new(),"hash").0,0.);}#[test]fn exact_fixture_arithmetic(){let golden:Value=serde_json::from_str(include_str!("../../../../../src/services/eval/fixtures/real_finance_salesforce_fy26_q1/golden.v1.json")).unwrap();let computed=calculations(&golden["inputs"]).unwrap();for metric in list(&golden["metrics"]){let id=metric["id"].as_str().unwrap();assert!((computed[id]-metric["expected"].as_f64().unwrap()).abs()<(metric["tolerance_abs"].as_f64().unwrap()/10.).max(1e-9),"{id}");}}}
